'use strict';
(() => {
const L = window.GroupPulseI18n, Text = window.GroupPulseText;
const $ = selector => document.querySelector(selector);
const e = value => String(value ?? '').replace(/[&<>"']/g, ch => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[ch]));
const t = key => L.t(key), number = value => Number(value || 0).toLocaleString(L.language === 'en' ? 'en-US' : 'zh-CN');
const date = (time, short = false) => time ? new Date(time * 1000).toLocaleString(L.language === 'en' ? 'en-US' : 'zh-CN', short ? { month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false } : { year:'numeric',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false }) : '—';
const dayKey = date => [date.getFullYear(),String(date.getMonth()+1).padStart(2,'0'),String(date.getDate()).padStart(2,'0')].join('-');
const initialRange = () => { const end = new Date(), start = new Date(); start.setDate(start.getDate()-6); return { start: dayKey(start), end: dayKey(end), preset:7 }; };
const defaults = () => ({ query:'',sender:'',match:'any',start:'',end:'',offset:0 });
const S = { boot:null,settings:{},view:'overview',groupIds:null,groupQuery:'',groups:[],expanded:new Set(),messages:new Map(),posts:new Map(),selected:null,ticket:0,results:{},threads:[],threadQuery:'',chatThread:'',chatReference:'',draft:{},modelPreview:null,modelResult:null,year:new Date().getFullYear(),loading:false,
  filters:{ search:defaults(),analysis:{...defaults(),...initialRange()},market:{query:'',exclude:'',hours:1,kind:'all',scope:'all',limit:60},prices:{...defaults(),...initialRange(),kind:'',min:'',max:'',sort:'newest'},chats:defaults(),moments:defaults(),contacts:defaults(),resources:defaults(),reports:defaults() } };
const icons = { overview:'<path d="M3 10 12 3l9 7v11h-6v-7H9v7H3Z"/>',search:'<circle cx="10.5" cy="10.5" r="7"/><path d="m16 16 5 5"/>',analysis:'<path d="M4 21V9m8 12V3m8 18V6M2 21h21"/>',market:'<path d="M3 7h17l-4-4m5 14H4l4 4M20 7l-4 4M4 17l4-4"/>',prices:'<path d="M3 4h9l10 10-8 8L3 11Z"/><circle cx="8" cy="8" r="1"/>',chats:'<path d="M21 11a9 9 0 0 1-13 8l-6 3 2-6A9 9 0 1 1 21 11Z"/>',moments:'<circle cx="12" cy="12" r="9"/><path d="m7 4 9 16M3 10h18M7 20l9-16"/>',contacts:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3Z"/>',resources:'<path d="M2 6h7l3 3h10v12H2Z"/>',saved:'<path d="m12 2 3 7 8 1-6 5 2 8-7-4-7 4 2-8-6-5 8-1Z"/>',reports:'<path d="M5 2h10l5 5v15H5Z M14 2v6h6M8 12h9M8 16h9"/>',exports:'<path d="M12 2v14m-5-5 5 5 5-5M3 17v5h18v-5"/>',settings:'<path d="m10 2-1 4-4 1-3 4 3 3 1 5 4 1 4 2 3-4 4-2-1-5 1-4-5-2Z"/><circle cx="12" cy="12" r="4"/>',arrow:'<path d="M4 20 20 4M5 4h15v15"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 17v2M1 12h3m17 0h2M4 4l2 2m12 12 2 2M20 4l-2 2M6 18l-2 2"/>',lock:'<rect x="5" y="10" width="14" height="12" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',copy:'<rect x="8" y="7" width="13" height="15" rx="2"/><path d="M16 7V2H2v15h6"/>' };
const icon = name => '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(icons[name]||icons.chats)+'</svg>';
const button = (key,action,classes='',extra='') => `<button type="button" class="${classes}" data-action="${action}" ${extra}>${e(t(key))}</button>`;
const field = (label,key,value,placeholder='',type='search',extra='') => `<label class="${extra.includes('small-field')?'small-field':'grow'}"><span>${e(t(label))}</span><input type="${type}" data-bind="${key}" value="${e(value)}" placeholder="${e(t(placeholder))}" ${extra.replace('small-field','')}></label>`;
const option = (value,key,current) => `<option value="${e(value)}"${String(current)===String(value)?' selected':''}>${e(t(key))}</option>`;
function hi(value,query,loose=false) { return Text.parts(String(value??''),Array.isArray(query)?query:Text.terms(query,loose),loose).map(part=>part.hit?'<mark>'+e(part.text)+'</mark>':e(part.text)).join(''); }
function preview(value,query,id,limit=420,loose=false) {
  const original=String(value??''); if(S.expanded.has(id)||original.length<=limit)return hi(original,query,loose);
  const result=Text.preview(original,Array.isArray(query)?query:Text.terms(query,loose),{maxChars:limit,loose});
  return result.fragments.map(part=>`<span class="gp-preview-fragment">${part.start?'… ':''}${hi(part.text,query,loose)}${part.end<original.length?' …':''}</span>`).join('');
}
const mediaURL=(kind,id,item='')=>'grouppulse-media://local/'+kind+'/'+encodeURIComponent(id)+(item!==''?'/'+item:'');
const avatar=(id,name)=>`<span class="avatar" aria-hidden="true">${e([...String(name||'?')][0])}<img src="${mediaURL('avatar',id)}" alt="" loading="lazy" data-hide-on-error="true"></span>`;
function getPath(key){return key.split('.').reduce((value,name)=>value?.[name],S);}
function setPath(key,value){const keys=key.split('.');let item=S;for(const name of keys.slice(0,-1))item=item[name]??=( {} );item[keys.at(-1)]=value;}
function remember(){for(const node of document.querySelectorAll('[data-bind]'))if(node.type!=='password')setPath(node.dataset.bind,node.type==='checkbox'?node.checked:node.value);}
async function api(action,value={}){const response=await window.groupPulse.invoke(action,value);if(!response?.ok)throw new Error(response?.error||'OPERATION_FAILED');return response.value;}
let toastTimer;
function notify(message,error=false){const node=$('#toast');node.textContent=message;node.classList.toggle('error',error);node.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{node.hidden=true;},error?9000:2600);}
function explain(error){const code=String(error?.message||error);if(L.messages[code])return t(code);if(/^MODEL_HTTP_/.test(code))return (L.language==='en'?'Model service returned HTTP ':'模型服务返回 HTTP ')+code.slice(11);if(/密钥|key|hmac|authentication/i.test(code))return t('DATABASE_KEY_INVALID');return t('OPERATION_FAILED');}
function theme(){const mode=S.settings.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):S.settings.theme||'light';document.documentElement.dataset.theme=mode;document.documentElement.lang=L.language;}
function stamp(){const current=S.boot?.current;return current?.updatedAt?new Date(current.updatedAt).toLocaleTimeString(L.language==='en'?'en-US':'zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false}):t('neverSynced');}
function renderFrame(){
  theme();const groups=[['workspace',['overview','search','analysis','market','prices']],['library',['chats','moments','contacts','resources']],['tools',['saved','reports','exports']]];
  $('#application').innerHTML=`<header class="titlebar"><span class="brand-small">GroupPulse</span><span class="crumb">${e(t('workspace'))} / <b id="crumb">${e(t(S.view))}</b></span><div class="status"><span class="status-dot"></span><span class="status-stamp" id="sync-stamp">${e(stamp())}</span>${button('sync','sync','quiet','id="sync-button"')}</div><label class="language">${e(t('language'))}<select id="language" data-action="language" aria-label="Language / 语言">${option('zh-CN','简体中文',L.language)}${option('en','English',L.language)}</select></label><div class="window-buttons"><button data-action="window" data-command="minimize" aria-label="${L.language==='en'?'Minimize':'最小化'}">−</button><button data-action="window" data-command="maximize" aria-label="${L.language==='en'?'Maximize':'最大化'}">□</button><button data-action="window" data-command="close" aria-label="${e(t('close'))}">×</button></div></header>`+
    (S.boot?.locked?`<div class="lock-screen"><form data-form="unlock" class="panel"><h2>${icon('lock')} GroupPulse</h2><label><span>${e(t('password'))}</span><input type="password" id="unlock-password" autocomplete="current-password" required></label><button class="primary" type="submit">${e(t('unlock'))}</button></form></div>`:
    `<div class="shell"><aside class="sidebar"><div class="brand"><img src="../../assets/icon.png" alt=""><div><b>GroupPulse</b><small>${e(t('tagline'))}</small></div></div><nav class="nav-scroll" aria-label="${e(t('workspace'))}">${groups.map(([title,views])=>`<div class="nav-heading">${e(t(title))}${S.settings.demo&&title==='workspace'?' · DEMO':''}</div>${views.map(view=>`<button class="nav-item ${S.view===view?'active':''}" data-action="navigate" data-view="${view}">${icon(view)}${e(t(view))}</button>`).join('')}`).join('')}</nav><div class="sidebar-footer"><button class="quiet" data-action="navigate" data-view="settings">${icon('settings')}${e(t('settings'))}</button><button class="quiet" data-action="theme" aria-label="${e(t('appearance'))}">${icon('sun')}</button><button class="quiet" data-action="lock" aria-label="${e(t('lock'))}">${icon('lock')}</button></div></aside><main class="page" id="page"></main><aside class="source-drawer" id="source-drawer" hidden></aside></div>`);
  if(!S.boot?.locked)renderDrawer();
}
function header(title,description='',actions='',eyebrow=true){return `<header class="page-header"><div>${eyebrow?'<div class="eyebrow">GROUPPULSE / '+e(t('workspace').toUpperCase())+'</div>':''}<h1>${e(t(title))}</h1>${description?'<p>'+e(t(description))+'</p>':''}</div><div class="actions">${actions}</div></header>`;}
function fieldFilters(view,{dates=true,sender=true,match=true}={}){
  const f=S.filters[view];return `<form data-form="filters" data-view="${view}"><div class="filters">${field('query',`filters.${view}.query`,f.query,'phraseHint')}${sender?field('sender',`filters.${view}.sender`,f.sender,'senderHint'):''}${match?`<label><span>${e(t('match'))}</span><select data-bind="filters.${view}.match">${option('any','any',f.match)}${option('all','allTerms',f.match)}</select></label>`:''}${dates?field('from',`filters.${view}.start`,f.start,'','date')+field('to',`filters.${view}.end`,f.end,'','date'):''}<div class="filter-actions"><button class="primary" type="submit">${e(t('searchButton'))}</button>${button('clear','clear-filters','',`data-view="${view}"`)}</div></div></form>`;
}
function rangeFilter(view){const f=S.filters[view];return `<div class="presets">${[[7,'last7'],[30,'last30'],[0,'allDates']].map(([days,key])=>`<button class="${Number(f.preset)===days?'active':''}" data-action="range" data-view="${view}" data-days="${days}">${e(t(key))}</button>`).join('')}</div>`;}
function groupScope(){return `<details class="scope"><summary>${e(t('groupScope'))} · ${S.groupIds===null?e(t('allGroups')):number(S.groupIds.length)+' '+e(t('groups'))}</summary><div class="scope-body"><div class="actions"><input type="search" id="group-query" data-action="group-query" placeholder="${e(t('groupName'))}" value="${e(S.groupQuery)}">${button('selectAll','select-groups')}${button('clearSelection','clear-groups')}</div><div class="scope-groups" id="scope-groups">${scopeGroups()}</div></div></details>`;}
function scopeGroups(){return S.groups.filter(group=>!S.groupQuery||(group.name+' '+group.id).toLowerCase().includes(S.groupQuery.toLowerCase())).map(group=>`<label class="check"><input type="checkbox" data-action="group" data-id="${e(group.id)}" ${S.groupIds===null||S.groupIds.includes(group.id)?'checked':''}><span title="${e(group.name)}">${hi(group.name,[S.groupQuery])}</span><small>${number(group.total)}</small></label>`).join('');}
function scopeOptions(view){const f=S.filters[view]||{};return {...f,...((view==='market'&&f.scope==='all')?{}:S.groupIds===null?{}:{groupIds:S.groupIds}),tracked:S.settings.tracked||[],ignore:S.settings.ignore||[]};}
function metric(value,label){return `<div class="metric"><strong>${number(value)}</strong><span>${e(t(label))}</span></div>`;}
function messageCard(message,{query='',loose=false,source=true}={}){
  S.messages.set(message.id,message);const body=message.body||t({3:'image',34:'voice',43:'video',47:'image',49:'file',10000:'systemMessage',10002:'systemMessage'}[message.type]||'other');
  const identity=[message.alias?`${t('alias')}: ${message.alias}`:'',`${message.senderId.startsWith('unknown:')?t('notRecorded'):'WXID: '+message.senderId}`].filter(Boolean).join(' · ');
  return `<article class="message-card ${S.selected?.id===message.id?'selected':''} ${message.sent?'sent':''}" data-ref="${e(message.id)}"><header class="message-meta">${message.intent?`<span class="tag ${message.intent}">${e(t(message.intent))}</span>`:''}<b>${hi(message.senderId.startsWith('unknown:')?t('unknownSender'):message.senderName,[...Text.terms(query,loose),S.filters[S.view]?.sender||''].filter(Boolean),loose)}</b><time>${e(date(message.timestamp,true))}</time></header><div class="message-id">${hi(identity,query,loose)}</div><div class="message-body">${preview(body,query,message.id,420,loose)}</div>${body.length>420?`<button class="quiet" data-action="expand" data-id="${e(message.id)}">${e(t(S.expanded.has(message.id)?'collapse':'expand'))}</button>`:''}${[3,47].includes(message.type)?`<div class="message-media">${mediaBox('message',message.id)}</div>`:''}${message.type===34?`<audio controls preload="none" src="${mediaURL('message',message.id)}" aria-label="${e(t('voice'))}"></audio>`:''}${message.type===43?`<video controls preload="none" class="message-media" src="${mediaURL('message',message.id)}" aria-label="${e(t('video'))}"></video>`:''}<footer class="message-footer"><span class="source-label">${hi(message.threadName,query,loose)}</span><div class="message-actions">${button('copy','copy','quiet',`data-id="${e(message.id)}"`)}${button('bookmark','bookmark','quiet',`data-id="${e(message.id)}"`)}${source?button('openSource','source','quiet',`data-id="${e(message.id)}"`):''}</div></footer>${message.sources?`<details class="sources"><summary>${number(message.sources.length)} ${e(t('sources'))} · ${e(t('allSources'))}</summary>${message.sources.map(item=>`<button data-action="source" data-id="${e(item.id)}">${e(item.threadName)} · ${e(date(item.timestamp,true))}</button>`).join('')}</details>`:''}</article>`;
}
function mediaBox(kind,id,item=''){const url=mediaURL(kind,id,item);return `<div class="media-box"><img src="${url}" alt="${e(t('image'))}" loading="lazy" data-action="image-preview" data-preview="${url}"><button data-action="retry-image" aria-label="${e(t('retry'))}" hidden>${e(t('noPreview'))}</button></div>`;}
function renderDrawer(){const host=$('#source-drawer');if(!host)return;if(!S.selected){host.hidden=true;return;}const m=S.selected,post=m.kind==='moment';host.hidden=false;host.innerHTML=`<div class="drawer-title"><h2>${e(t('source'))}</h2><button class="quiet" data-action="close-source" aria-label="${e(t('close'))}">${icon('close')}</button></div><h3>${e(post?m.author_name:m.senderId.startsWith('unknown:')?t('unknownSender'):m.senderName)}</h3><dl class="source-dl"><dt>WXID</dt><dd class="mono">${e(post?m.author:m.senderId)}</dd>${post?'':`<dt>${e(t('alias'))}</dt><dd>${e(m.alias||t('notRecorded'))}</dd><dt>${e(t('nickname'))}</dt><dd>${e(m.nickname||t('notRecorded'))}</dd><dt>${e(t('remark'))}</dt><dd>${e(m.remark||t('notRecorded'))}</dd><dt>${e(t('groupScope'))}</dt><dd>${e(m.threadName)}</dd><dt>${e(t('localId'))}</dt><dd class="mono">${e(m.localId)}</dd><dt>${e(t('shard'))}</dt><dd class="mono">${e(m.shard)}</dd>`}<dt>${e(t('time'))}</dt><dd>${e(date(post?m.time:m.timestamp))}</dd></dl><div class="original">${e(m.body||m.raw)}</div>${m.raw&&m.raw!==m.body?`<details class="gap-top"><summary>${e(t('rawStructure'))}</summary><pre class="original">${e(m.raw)}</pre></details>`:''}<div class="actions">${button('copy','drawer-copy')}${post?'':button('copySource','drawer-copy-source')+button('copyIdentity','drawer-identity')+button('viewContext','context','primary')}</div>`;}
function renderOverview(data){
  const content=data?`<div class="home-grid"><section class="panel"><div class="panel-header"><h2>${e(t('last24'))}</h2><small>${e(t('localOnly'))}</small></div><div class="metrics">${metric(data.summary.messages,'messages')}${metric(data.summary.groups,'groups')}${metric(data.summary.text,'textMessages')}</div><div class="panel-header"><h3>${e(t('activeGroups'))}</h3><small>${e(t('messageCount'))}</small></div><div class="rank-list">${data.groups.slice(0,8).map((group,i)=>`<button class="rank" data-action="analyze-group" data-id="${e(group.id)}"><span class="order">${String(i+1).padStart(2,'0')}</span><span class="rank-name"><b>${e(group.name)}</b><small>${e(date(group.latest,true))}</small></span><span class="number">${number(group.count)}</span><span class="rank-track"><i style="width:${group.count/(data.groups[0]?.count||1)*100}%"></i></span>→</button>`).join('')||`<div class="empty">${e(t('noResults'))}</div>`}</div></section><section><h2 style="margin-bottom:16px">${e(t('continueWork'))}</h2><div class="workflows">${[['market','openMarket'],['analysis','openAnalysis'],['prices','openPrices']].map(([view,key])=>`<button class="workflow" data-action="navigate" data-view="${view}"><span class="icon-box">${icon(view)}</span><span><strong>${e(t(view))}</strong><small>${e(t(key))}</small></span></button>`).join('')}</div><div class="ai-note"><h3>${e(t('ai'))}</h3><p class="hint">${e(t('modelHelp'))}</p>${button('models','navigate','quiet','data-view="settings"')}</div></section></div>`:`<div class="loading-line">${e(t('loading'))}</div>`;
  return header('overview','searchHome')+`<form class="home-search" data-form="home-search"><input type="search" id="home-query" placeholder="${e(t('queryHint'))}" aria-label="${e(t('searchAll'))}" value="${e(S.filters.search.query)}"><button class="primary" type="submit">${e(t('searchButton'))} ${icon('arrow')}</button></form><div class="tracked-row"><span>${e(t('tracked'))}</span>${(S.settings.tracked||[]).map(word=>`<button data-action="keyword" data-term="${e(word)}">${e(word)}</button>`).join('')}</div>`+content;
}
function renderStatistics(data){
  if(!data)return `<div class="loading-line">${e(t('loading'))}</div>`;
  const max=Math.max(1,...data.days.map(day=>day.count));
  return `<div class="metrics">${metric(data.summary.messages,'messages')}${metric(data.summary.groups,'groups')}${metric(data.summary.senders,'senders')}</div><div class="section-grid"><section class="panel"><h2>${e(t('topKeywords'))}</h2><div class="keyword-list gap-top">${data.keywords.map(word=>`<button data-action="keyword" data-term="${e(word.term)}">${e(word.term)}<span class="frequency">${number(word.messages)}</span></button>`).join('')||e(t('noResults'))}</div></section><section class="panel"><h2>${e(t('daily'))}</h2><div class="chart" role="img" aria-label="${e(t('daily'))}">${data.days.map(day=>`<div class="chart-bar" style="height:${Math.max(2,day.count/max*100)}%" title="${e(day.day)}: ${number(day.count)}"></div>`).join('')}</div><div class="chart-footer"><span>${e(data.days[0]?.day||'')}</span><span>${e(data.days.at(-1)?.day||'')}</span></div></section></div><section class="panel gap-top"><h2>${e(t('tracked'))}</h2><p class="hint">${e(t('trackHelp'))}</p><form class="track-editor gap-top" data-form="tracked"><textarea id="tracked-words" placeholder="${e(t('trackPlaceholder'))}">${e((S.settings.tracked||[]).join('\n'))}</textarea><button type="submit">${e(t('saveTracked'))}</button></form><div class="table-wrap"><table class="table"><thead><tr><th>${e(t('query'))}</th><th>${e(t('messageHits'))}</th><th>${e(t('occurrences'))}</th><th>${e(t('groupHits'))}</th><th>${e(t('senderHits'))}</th></tr></thead><tbody>${data.tracked.map(item=>`<tr><td><button class="quiet" data-action="keyword" data-term="${e(item.term)}">${e(item.term)}</button></td><td>${number(item.messages)}</td><td>${number(item.occurrences)}</td><td>${number(item.groups)}</td><td>${number(item.senders)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>${e(t('types'))}</h2><div class="tracked-row gap-top">${data.types.map(item=>`<span class="tag">${e(typeName(item.type))} · ${number(item.count)}</span>`).join('')}</div></section>`;
}
function typeName(type){return t({1:'text',3:'image',34:'voice',43:'video',47:'image',49:'link',10000:'systemMessage',10002:'systemMessage'}[type]||'other');}
function aiArea(){const result=S.modelResult;return `<section class="ai-layout"><h2>${e(t('ai'))}</h2><p class="hint">${e(t('modelHelp'))}</p><form class="ai-form gap-top" data-form="ai-preview"><label><span>${e(t('question'))}</span><textarea id="ai-question" data-bind="draft.question" placeholder="${e(t('questionHint'))}">${e(S.draft.question||'')}</textarea></label><button type="submit">${e(t('prepareAI'))}</button></form>${S.modelPreview?`<div class="info-box"><b>${e(t('destination'))}: ${e(S.modelPreview.destination)}</b><br>${e(S.modelPreview.model)} · ${number(S.modelPreview.samples)} ${e(t('samples'))} · ${number(S.modelPreview.characters)} ${e(t('characters'))}<br>${number(S.modelPreview.eligible)} ${e(t('eligible'))}<div class="actions gap-top">${button('runAI','run-ai','primary')}${button('stop','cancel')}</div></div>`:''}${result?`<div class="ai-result">${e(result.text)}</div><div class="ai-evidence">${result.evidence.samples.map(sample=>`<button data-action="source" data-id="${e(sample.id)}">[${e(sample.number)}]</button>`).join('')}</div><p class="hint">${e(t('aiSamplesNote'))}</p>`:''}</section>`;}
function renderMarket(data){
  const f=S.filters.market;return header('market','matchingNote',button('exportCSV','export','',`data-format="csv"`)+button('collect','collect','primary'))+`<div class="filters"><label><span>${e(t('hours'))}</span><select data-bind="filters.market.hours">${[1,3,6,24].map(hour=>option(hour,'hour'+hour,f.hours)).join('')}</select></label><label><span>${e(t('groupScope'))}</span><select data-bind="filters.market.scope">${option('all','allGroups',f.scope)}${option('selected','selectedGroups',f.scope)}</select></label><label class="check"><input type="checkbox" id="auto-collect" data-action="auto-collect" ${S.settings.autoCollect!==false?'checked':''}>${e(t('autoCollect'))}</label></div>${f.scope==='selected'?groupScope():''}<div class="metrics market-metrics">${metric(data?.totals.all,'listings')}${metric(data?.groups,'coverageGroups')}${metric(data?.checked,'checked')}${metric(data?.authors,'identifiedSenders')}</div><div class="market-toolbar"><div class="tabs" role="tablist" aria-label="${e(t('market'))}">${[['pairs',data?.pairCount??data?.pairs.length],['all',data?.totals.all],['offer',data?.totals.offer],['request',data?.totals.request],['review',data?.totals.review]].map(([kind,count])=>`<button role="tab" aria-selected="${f.kind===kind}" class="${f.kind===kind?'active':''}" data-action="market-tab" data-kind="${kind}">${e(t(kind))}<span class="count">${number(count)}</span></button>`).join('')}</div><form data-form="market-search">${field('searchButton','filters.market.query',f.query,'queryHint')}${field('blocked','filters.market.exclude',f.exclude,'blockedHint')}<button class="primary" type="submit">${e(t('searchButton'))}</button>${button('clear','clear-market')}</form></div><p class="hint">${e(t('marketHint'))}</p>${data?`<p class="result-note">${number(f.kind==='pairs'?(data.pairCount??data.pairs.length):data.filtered)} ${e(t('results'))} · ${e(t('exportHelp'))}</p><div class="market-grid">${f.kind==='pairs'?data.pairs.slice(0,f.limit).map(pair=>`<section class="pair"><div class="pair-head">${pair.shared.map(term=>'<span>'+hi(term,f.query,true)+'</span>').join(' · ')}</div><div class="pair-sides">${messageCard(pair.offer,{query:f.query,loose:true})}${messageCard(pair.request,{query:f.query,loose:true})}</div></section>`).join(''):data.listings.slice(0,f.limit).map(message=>messageCard(message,{query:f.query,loose:true})).join('')}</div>${((f.kind==='pairs'?Math.min(data.pairCount??data.pairs.length,data.pairDisplayLimit??Infinity):data.filtered)>f.limit)?button('more','more-market','load-more'):''}${!(f.kind==='pairs'?data.pairs.length:data.listings.length)?`<div class="empty">${e(t('noResults'))}</div>`:''}`:`<div class="loading-line">${e(t('loading'))}</div>`}`;
}
function unitName(unit){return String(unit).replace('折',t('discountUnit')).replace('倍','×').replace('币种未注',t('unknownCurrency')).replace('周期未注',t('unknownPeriod')).replace('/月',L.language==='en'?'/month':'/月').replace('/年',L.language==='en'?'/year':'/年').replace('/天',L.language==='en'?'/day':'/天').replace('/日',L.language==='en'?'/day':'/日');}
function priceFilters(){const f=S.filters.prices;return `<form data-form="filters" data-view="prices"><div class="filters"><label><span>${e(t('quoteType'))}</span><select data-bind="filters.prices.kind">${['','discount','perUSD','multiplier','tier','amount'].map(key=>option(key,key||'all',f.kind)).join('')}</select></label>${field('query','filters.prices.query',f.query,'queryHint')}<button class="primary" type="submit">${e(t('apply'))}</button>${button('reset','clear-filters','',`data-view="prices"`)}</div><details class="advanced-filters"><summary>${e(t('moreFilters'))}</summary><div class="filters gap-top">${field('sender','filters.prices.sender',f.sender,'senderHint')}${field('min','filters.prices.min',f.min,'','number','small-field step="any"')}${field('max','filters.prices.max',f.max,'','number','small-field step="any"')}${field('from','filters.prices.start',f.start,'','date')}${field('to','filters.prices.end',f.end,'','date')}<label><span>${e(t('quoteSort'))}</span><select data-bind="filters.prices.sort">${option('newest','newest',f.sort)}${option('value-asc','lowest',f.sort)}${option('value-desc','highest',f.sort)}</select></label><button type="submit">${e(t('apply'))}</button></div></details></form>`;}
function renderPrices(data){const f=S.filters.prices;return header('prices','priceBoundary',button('exportCSV','export','',`data-format="csv"`))+groupScope()+rangeFilter('prices')+`${priceFilters()}${data?`<div class="metrics">${metric(data.count,'quoteMentions')}${metric(data.uniqueQuotes,'uniqueQuotes')}${metric(data.reviewCount,'needsReview')}</div><details class="panel"><summary>${e(t('distribution'))}</summary><div class="table-wrap gap-top"><table class="table"><thead><tr>${['product','unit','value','quoteMentions','uniqueQuotes','senders'].map(key=>'<th>'+e(t(key))+'</th>').join('')}</tr></thead><tbody>${data.buckets.map(bucket=>`<tr><td>${e(bucket.product==='未注明商品'?t('unspecifiedProduct'):bucket.product)}${bucket.review?'<small>'+e(t('review'))+'</small>':''}</td><td>${e(t(bucket.kind))}<small>${e(unitName(bucket.unit))}</small></td><td class="numeric">${e(bucket.value)}${bucket.high===null?'':'–'+e(bucket.high)}</td><td>${number(bucket.mentions)}</td><td>${number(bucket.uniqueQuotes)}</td><td>${number(bucket.senders)}</td></tr>`).join('')}</tbody></table></div></details><div>${data.records.map(row=>`<article class="quote-card"><div class="quote-head"><strong>${e(row.quote.value)}${row.quote.high===null?'':'–'+e(row.quote.high)} ${e(unitName(row.quote.unit))}</strong><span>${e(t(row.quote.kind))}</span><span>${e(row.quote.product==='未注明商品'?t('unspecifiedProduct'):row.quote.product)}</span>${row.quote.review?'<span class="tag review">'+e(t('review'))+'</span>':''}</div><div class="quote-context">${hi(row.quote.context,[row.quote.raw,...Text.terms(f.query)])}</div>${messageCard(row.message,{query:[row.quote.raw,...Text.terms(f.query)]})}</article>`).join('')||'<div class="empty">'+e(t('noResults'))+'</div>'}</div>${data.hasMore?button('more','more','load-more','data-view="prices"'):''}`:`<div class="loading-line">${e(t('loading'))}</div>`}`;}
function chatFilters(){const f=S.filters.chats;return `<form data-form="filters" data-view="chats"><div class="filters">${field('query','filters.chats.query',f.query,'phraseHint')}<button class="primary" type="submit">${e(t('searchButton'))}</button>${button('clear','clear-filters','',`data-view="chats"`)}</div><details class="chat-advanced"><summary>${e(t('sender'))} · ${e(t('from'))} · ${e(t('match'))}</summary><div class="filters">${field('sender','filters.chats.sender',f.sender,'senderHint')}${field('from','filters.chats.start',f.start,'','date')}${field('to','filters.chats.end',f.end,'','date')}<label><span>${e(t('match'))}</span><select data-bind="filters.chats.match">${option('any','any',f.match)}${option('all','allTerms',f.match)}</select></label><button type="submit">${e(t('apply'))}</button></div></details></form>`;}
function renderChats(data){const thread=S.threads.find(thread=>thread.id===S.chatThread);return header('chats','localOnly',button('exportCSV','export','',`data-format="csv"`))+`<div class="split"><section class="thread-list"><form data-form="thread-search"><input type="search" data-bind="threadQuery" value="${e(S.threadQuery)}" placeholder="${e(t('searchButton'))}" aria-label="${e(t('chats'))}"><button type="submit">${e(t('searchButton'))}</button></form><div class="threads">${S.threads.map(thread=>`<button class="thread ${S.chatThread===thread.id?'active':''}" data-action="thread" data-id="${e(thread.id)}">${avatar(thread.id,thread.name)}<span class="thread-copy"><strong>${hi(thread.name,[S.threadQuery])}</strong><small>${hi(thread.summary.slice(0,65),[S.threadQuery])}</small></span><span class="count">${number(thread.total)}</span></button>`).join('')}</div></section><section class="chat-area">${thread?`<div class="chat-header">${avatar(thread.id,thread.name)}<div><h2>${e(thread.name)}</h2><small class="mono">${e(thread.id)}</small></div></div>`:''}${chatFilters()}${S.chatReference?`<div class="info-box">${e(t('contextNotice'))} ${button('clear','clear-context','quiet')}</div>`:''}<div class="result-note">${number(data?.total)} ${e(t('results'))}</div><div>${data?data.items.map(message=>messageCard(message,{query:S.filters.chats.query})).join('')||'<div class="empty">'+e(t('noResults'))+'</div>':'<div class="loading-line">'+e(t('loading'))+'</div>'}</div>${data?.hasMore?button('more','more','load-more','data-view="chats"'):''}</section></div>`;}
function renderContacts(data){return header('contacts','senderDetails')+fieldFilters('contacts',{dates:false,sender:false,match:false})+`<div class="result-note">${number(data?.total)} ${e(t('results'))}</div><div class="contact-grid">${data?data.items.map(contact=>`<article class="contact"><header class="contact-head">${avatar(contact.id,contact.name)}<b>${hi(contact.name,[S.filters.contacts.query])}</b></header><dl><dt>WXID</dt><dd>${hi(contact.id,[S.filters.contacts.query])}</dd><dt>${e(t('alias'))}</dt><dd>${hi(contact.alias||t('notRecorded'),[S.filters.contacts.query])}</dd><dt>${e(t('nickname'))}</dt><dd>${hi(contact.nickname,[S.filters.contacts.query])}</dd><dt>${e(t('remark'))}</dt><dd>${hi(contact.remark||t('notRecorded'),[S.filters.contacts.query])}</dd></dl><div class="actions">${button('copyIdentity','copy-text','',`data-text="${e([contact.name,contact.id,contact.alias].filter(Boolean).join('\n'))}"`)}${button('chats','contact-chat','',`data-id="${e(contact.id)}"`)}${button('moments','contact-moments','',`data-id="${e(contact.id)}"`)}</div></article>`).join(''):'<div class="loading-line">'+e(t('loading'))+'</div>'}</div>${data?.hasMore?button('more','more','load-more','data-view="contacts"'):''}`;}
function renderMoments(data){return header('moments','mediaHelp',button('exportCSV','export','',`data-format="csv"`))+fieldFilters('moments',{sender:false,match:false})+(S.filters.moments.author?'<div class="info-box">'+e(S.filters.moments.author)+' '+button('clear','clear-author','quiet')+'</div>':'')+`<div class="result-note">${number(data?.total)} ${e(t('results'))}</div>${data?data.items.map(post=>{S.posts.set(post.id,post);return `<article class="moment">${avatar(post.author,post.author_name)}<div class="moment-content"><header><b>${hi(post.author_name,[S.filters.moments.query])}</b><time>${e(date(post.time))}</time></header><small class="mono">${hi(post.author,[S.filters.moments.query])}</small><div class="message-body">${preview(post.body,[S.filters.moments.query],'moment:'+post.id,500)}</div>${post.body.length>500?button(S.expanded.has('moment:'+post.id)?'collapse':'expand','expand','quiet',`data-id="moment:${e(post.id)}"`):''}<div class="moment-media">${post.media.map((item,i)=>['6','15'].includes(item.type)?`<video controls preload="none" src="${mediaURL('moment',post.id,i)}" aria-label="${e(t('video'))}"></video>`:mediaBox('moment',post.id,i)).join('')}</div><div class="message-actions gap-top">${button('copy','copy-text','quiet',`data-text="${e(post.body)}"`)}${button('source','moment-source','quiet',`data-id="${e(post.id)}"`)}</div></div></article>`;}).join('')||'<div class="empty">'+e(t('noResults'))+'</div>':'<div class="loading-line">'+e(t('loading'))+'</div>'}${data?.hasMore?button('more','more','load-more','data-view="moments"'):''}`;}
function renderResources(data){return header('resources','mediaHelp',button('chooseMedia','choose-media'))+fieldFilters('resources',{dates:false,sender:false,match:false})+`<div class="result-note">${number(data?.total)} ${e(t('results'))}</div><div class="contact-grid">${data?data.items.map(item=>`<article class="contact">${mediaBox('resource',item.key)}<h3 class="gap-top" style="overflow-wrap:anywhere">${hi(item.path.split(/[/\\]/).at(-1),[S.filters.resources.query])}</h3><p class="hint">${e(item.extension.toUpperCase())} · ${number(item.size/1024)} KB</p><details><summary class="hint">${e(t('source'))}</summary><small style="overflow-wrap:anywhere">${e(item.path)}</small></details>${button('source','reveal-resource','quiet',`data-key="${e(item.key)}"`)}</article>`).join(''):'<div class="loading-line">'+e(t('loading'))+'</div>'}</div>${data?.hasMore?button('more','more','load-more','data-view="resources"'):''}`;}
function renderSettings(){const draft=S.draft.model||S.settings.model||{};return header('settings','independent')+`<div class="settings-grid"><section class="panel"><h2>${e(t('general'))}</h2><form class="settings-form gap-top" data-form="general"><label><span>${e(t('appearance'))}</span><select id="theme-setting">${['light','dark','system'].map(key=>option(key,key,S.settings.theme)).join('')}</select></label><label class="check"><input type="checkbox" id="auto-sync" ${S.settings.autoSync?'checked':''}>${e(t('autoSync'))}</label><label class="check"><input type="checkbox" id="remote-media" ${S.settings.remoteMedia?'checked':''}>${e(t('remoteMedia'))}</label><p class="hint">${e(t('mediaHelp'))}</p><button class="primary" type="submit">${e(t('saveSettings'))}</button></form><div class="settings-section"><h3>${e(t('import'))}</h3><p class="hint mono">${e(S.settings.source?.databaseRoot||t('noData'))}</p>${button('import','open-import','gap-top')}<p class="hint">${e(t('mediaFolder'))}: ${e(S.settings.source?.mediaRoot||'—')}</p>${button('chooseMedia','choose-media','gap-top')}<p class="hint">${e(t('decoderHelp'))}</p>${button('chooseDecoder','choose-decoder','gap-top')}</div></section><section class="panel"><h2>${e(t('models'))}</h2><p class="hint">${e(t('modelHelp'))}</p><form class="settings-form gap-top" data-form="model"><label><span>${e(t('baseURL'))}</span><input type="url" data-bind="draft.model.baseURL" value="${e(draft.baseURL||'')}" placeholder="https://api.example.com/v1" required></label><label><span>${e(t('model'))}</span><input type="text" data-bind="draft.model.model" value="${e(draft.model||'')}" required></label><label><span>${e(t('protocol'))}</span><select data-bind="draft.model.protocol">${[['openai','OpenAI compatible'],['responses','Responses'],['anthropic','Anthropic Messages'],['google','Google Gemini']].map(([value,label])=>`<option value="${value}" ${(draft.protocol||'openai')===value?'selected':''}>${e(label)}</option>`).join('')}</select></label><label><span>${e(t('apiKey'))}</span><input type="password" id="model-key" autocomplete="off" placeholder="${S.settings.hasModelKey?e(t('savedKey')):''}"></label><button class="primary" type="submit">${e(t('saveModel'))}</button></form><p class="hint">${e(t('securityNote'))}</p></section><section class="panel"><h2>${e(t('localSecurity'))}</h2><form class="settings-form gap-top" data-form="lock-password"><label><span>${e(t('setPassword'))}</span><input type="password" id="new-password" minlength="6" autocomplete="new-password" required></label><p class="hint">${e(t('passwordHelp'))}</p><button type="submit">${e(t('savePassword'))}</button>${S.settings.lockEnabled?button('disableLock','disable-lock','danger'):''}</form></section><section class="panel"><h2>${e(t('about'))}</h2><p class="gap-top">GroupPulse ${e(S.boot.version)}</p><p class="hint">${e(t('independent'))}</p><p class="hint">${e(t('licenseDetail'))}</p><p class="hint">${e(t('localOnly'))}</p>${button('sourceProject','project','gap-top')}</section></div>`;}
function renderImport(inDialog=false){return `${inDialog?'':header('import','independent')}<section class="${inDialog?'':'import-card'}">${inDialog?'':'<img class="icon-large" src="../../assets/icon.png" alt=""><h1>'+e(t('importFirst'))+'</h1>'}<p>${e(t('importIntro'))}</p>${button('chooseFolder','choose-source','primary')}${S.draft.source?`<div class="source-choice"><b>${e(S.draft.source.folderName)}</b> · ${e(t(S.draft.source.encrypted?'encrypted':'plaintext'))}<br>${e(S.draft.source.databaseRoot)}</div><form class="settings-form gap-top" data-form="import"><label><span>${e(t('selfId'))}</span><input type="text" id="self-id" value="${e(S.draft.selfId||'')}" placeholder="wxid_..."></label><p class="hint">${e(t('selfHelp'))}</p>${S.draft.source.encrypted?`<label><span>${e(t('dbKey'))}</span><input type="password" id="database-key" autocomplete="off" maxlength="64" placeholder="${S.draft.keyLoaded?'✓':''}"></label><p class="hint">${e(t('keyHelp'))}</p><label class="check"><input type="checkbox" id="remember-key" checked>${e(t('rememberKey'))}</label><div class="actions">${S.boot.platform==='win32'?button('keyInfo','key-info'):button('capture','capture-key')}</div>`:''}<button class="primary" type="submit">${e(t('importOpen'))}</button></form>`:''}</section>`;}
function renderExports(){return header('exports','exportHelp')+groupScope()+fieldFilters('search')+`<section class="panel"><h2>${e(t('export'))}</h2><div class="export-options"><button class="export-option" data-action="export" data-format="csv">${icon('exports')}${e(t('exportCSV'))}</button><button class="export-option" data-action="export" data-format="json">${icon('reports')}${e(t('exportJSON'))}</button></div><p class="hint">${e(t('exportHelp'))}</p></section>`;}
function renderView(){
  const page=$('#page');if(!page)return;const data=S.results[S.view];
  if(!S.boot.current?.index&&S.view!=='settings'){page.innerHTML=renderImport();return;}
  const exportsButton=button('exportCSV','export','',`data-format="csv"`);
  if(S.view==='overview')page.innerHTML=renderOverview(data);
  else if(S.view==='search')page.innerHTML=header('search','searchHome',exportsButton)+groupScope()+fieldFilters('search')+`<p class="result-note">${number(data?.total)} ${e(t('results'))}</p><div class="message-list">${data?data.items.map(message=>messageCard(message,{query:S.filters.search.query})).join('')||'<div class="empty">'+e(t('noResults'))+'</div>':'<div class="loading-line">'+e(t('loading'))+'</div>'}</div>${data?.hasMore?button('more','more','load-more','data-view="search"'):''}`;
  else if(S.view==='analysis')page.innerHTML=header('analysis','localOnly',exportsButton)+groupScope()+rangeFilter('analysis')+fieldFilters('analysis',{sender:false})+renderStatistics(data)+aiArea();
  else if(S.view==='market')page.innerHTML=renderMarket(data);
  else if(S.view==='prices')page.innerHTML=renderPrices(data);
  else if(S.view==='chats')page.innerHTML=renderChats(data);
  else if(S.view==='contacts')page.innerHTML=renderContacts(data);
  else if(S.view==='moments')page.innerHTML=renderMoments(data);
  else if(S.view==='resources')page.innerHTML=renderResources(data);
  else if(S.view==='settings')page.innerHTML=renderSettings();
  else if(S.view==='exports')page.innerHTML=renderExports();
  else if(S.view==='reports')page.innerHTML=header('reports','reportHelp',button('exportHTML','export-report'))+`<form class="report-year" data-form="report"><label><span>${e(t('year'))}</span><input type="number" min="2000" max="2100" data-bind="year" value="${e(S.year)}"></label><button class="primary" type="submit">${e(t('generateReport'))}</button></form>`+renderStatistics(data);
  else if(S.view==='saved')page.innerHTML=header('saved','source')+`<div class="message-list">${data?data.map(message=>`<article class="message-card"><div class="message-meta"><b>${e(message.senderName)}</b><time>${e(date(message.timestamp,true))}</time></div><div class="message-body">${preview(message.body,[],message.id,500)}</div><footer class="message-footer"><span>${e(message.threadName)}</span>${button('openSource','source','quiet',`data-id="${e(message.id)}"`)}${button('removeBookmark','bookmark','quiet',`data-id="${e(message.id)}"`)}</footer></article>`).join('')||'<div class="empty">'+e(t('noResults'))+'</div>':'<div class="loading-line">'+e(t('loading'))+'</div>'}</div>`;
  page.insertAdjacentHTML('beforeend',`<div class="footer-note">${e(t('localOnly'))}${S.settings.demo?' · '+e(t('demo')):''} · GroupPulse ${e(S.boot.version)}</div>`);
  if($('#crumb'))$('#crumb').textContent=t(S.view);document.title='GroupPulse · '+t(S.view);
}
async function loadView({cached=false,append=false}={}){
  remember();const view=S.view,ticket=++S.ticket;
  renderView();if(cached&&S.results[view])return;
  if(!S.boot.current?.index||['settings','exports'].includes(view))return;
  let result;
  try{
    if(['analysis','prices','search','market'].includes(view)&&!S.groups.length)S.groups=(await api('threads',{groupsOnly:true})).items;
    if(view==='overview')result=await api('dashboard',{tracked:S.settings.tracked||[]});
    else if(view==='analysis')result=await api('statistics',scopeOptions(view));
    else if(view==='reports')result=await api('statistics',{start:S.year+'-01-01',end:S.year+'-12-31',groupsOnly:false,tracked:S.settings.tracked||[]});
    else if(view==='search')result=await api('messages',{...scopeOptions(view),groupsOnly:true});
    else if(view==='market')result=await api('market',scopeOptions(view));
    else if(view==='prices')result=await api('prices',scopeOptions(view));
    else if(view==='chats'){
      S.threads=(await api('threads',{query:S.threadQuery})).items;if(!S.chatThread)S.chatThread=S.threads[0]?.id||'';
      result=await api('messages',{...S.filters.chats,thread:S.chatThread,reference:S.chatReference});
    }else if(['contacts','moments','resources'].includes(view))result=await api(view,S.filters[view]);
    else if(view==='saved')result=await api('saved');
    if(ticket!==S.ticket||view!==S.view)return;
    if(append&&S.results[view]?.items&&result?.items)result.items=[...S.results[view].items,...result.items];
    if(append&&view==='prices'&&S.results.prices?.records)result.records=[...S.results.prices.records,...result.records];
    S.results[view]=result;remember();renderView();renderDrawer();
    if(S.chatReference&&view==='chats')document.querySelector(`[data-ref="${S.chatReference}"]`)?.scrollIntoView({block:'center'});
  }catch(error){if(ticket===S.ticket)notify(explain(error),true);}
}
async function navigate(view){remember();S.view=view;S.ticket++;renderFrame();await loadView({cached:true});if(!(view==='chats'&&S.chatReference))$('#page')?.scrollTo(0,0);}
async function source(id){S.selected=S.messages.get(id)||await api('message',id);if(!S.selected)throw Error('MESSAGE_NOT_FOUND');renderDrawer();}
function showImport(){const dialog=$('#dialog');dialog.innerHTML=`<div class="dialog-header"><h2>${e(t('import'))}</h2>${button('close','close-dialog','quiet')}</div>${renderImport(true)}`;if(!dialog.open)dialog.showModal();}
async function saveSettings(value){const current=await api('saveSettings',value);S.settings=current;L.language=current.language||'zh-CN';theme();return current;}
function restoreSelection(){const selected=new Set(S.groupIds===null?S.groups.map(group=>group.id):S.groupIds);return selected;}
async function action(name,node){
  remember();
  if(name==='window')return api('window',{command:node.dataset.command});
  if(name==='navigate')return navigate(node.dataset.view);
  if(name==='source')return source(node.dataset.id);
  if(name==='close-source'){S.selected=null;return renderDrawer();}
  if(name==='context'){const m=S.selected;S.expanded.add(m.id);S.filters.chats.query=S.filters[S.view]?.query||'';S.chatThread=m.threadId;S.chatReference=m.id;delete S.results.chats;return navigate('chats');}
  if(name==='clear-context'){S.chatReference='';return loadView();}
  if(name==='expand'){S.expanded.has(node.dataset.id)?S.expanded.delete(node.dataset.id):S.expanded.add(node.dataset.id);return renderView();}
  if(name==='copy'){await api('copy',{id:node.dataset.id});return notify(t('copied'));}
  if(name==='copy-text'){await api('copyText',{text:node.dataset.text});return notify(t('copied'));}
  if(name==='drawer-copy'){if(S.selected.kind==='moment')await api('copyText',{text:S.selected.body});else await api('copy',{id:S.selected.id});return notify(t('copied'));}
  if(name==='drawer-copy-source'||name==='drawer-identity'){await api('copy',{id:S.selected.id,mode:name==='drawer-identity'?'identity':'source'});return notify(t('copied'));}
  if(name==='moment-source'){S.selected={...S.posts.get(node.dataset.id),kind:'moment'};return renderDrawer();}
  if(name==='bookmark'){await api('saveMessage',{id:node.dataset.id});notify(t('savedNotice'));if(S.view==='saved')return loadView();return;}
  if(name==='theme'){await saveSettings({theme:document.documentElement.dataset.theme==='dark'?'light':'dark'});renderFrame();return loadView({cached:true});}
  if(name==='language'){await saveSettings({language:node.value});S.modelPreview=null;renderFrame();return loadView({cached:true});}
  if(name==='keyword'){S.filters.search.query=node.dataset.term;S.filters.search.offset=0;delete S.results.search;return navigate('search');}
  if(name==='analyze-group'){S.groupIds=[node.dataset.id];delete S.results.analysis;return navigate('analysis');}
  if(name==='range'){const f=S.filters[node.dataset.view],days=Number(node.dataset.days),end=new Date(),start=new Date();start.setDate(start.getDate()-Math.max(0,days-1));f.start=days?dayKey(start):'';f.end=days?dayKey(end):'';f.preset=days;f.offset=0;return loadView();}
  if(name==='select-groups'||name==='clear-groups'){S.groupIds=name==='select-groups'?null:[];return renderView();}
  if(name==='group'){const selected=restoreSelection();node.checked?selected.add(node.dataset.id):selected.delete(node.dataset.id);S.groupIds=[...selected];return;}
  if(name==='clear-filters'){const view=node.dataset.view;S.filters[view]=view==='prices'?{...defaults(),...initialRange(),kind:'',min:'',max:'',sort:'newest'}:defaults();if(view==='chats')S.chatReference='';delete S.results[view];return loadView();}
  if(name==='clear-market'){S.filters.market.query='';S.filters.market.exclude='';S.filters.market.limit=60;return loadView();}
  if(name==='market-tab'){S.filters.market.kind=node.dataset.kind;S.filters.market.limit=60;return loadView();}
  if(name==='more-market'){S.filters.market.limit=Math.min(2000,S.filters.market.limit+60);return renderView();}
  if(name==='more'){S.filters[node.dataset.view].offset=Number(S.filters[node.dataset.view].offset||0)+(node.dataset.view==='moments'?40:node.dataset.view==='contacts'||node.dataset.view==='resources'||node.dataset.view==='prices'?100:80);return loadView({append:true});}
  if(name==='thread'||name==='contact-chat'){S.chatThread=node.dataset.id;S.chatReference='';S.filters.chats.offset=0;delete S.results.chats;return S.view==='chats'?loadView():navigate('chats');}
  if(name==='contact-moments'){S.filters.moments.author=node.dataset.id;S.filters.moments.offset=0;delete S.results.moments;return navigate('moments');}
  if(name==='clear-author'){delete S.filters.moments.author;return loadView();}
  if(name==='sync'||name==='collect'){
    const control=$('#sync-button');if(control)control.disabled=true;
    try{await api('refresh');S.boot=await api('bootstrap');S.results={};S.groups=[];await loadView();}finally{if(control)control.disabled=false;}return;
  }
  if(name==='cancel')return api('cancel');
  if(name==='open-import')return showImport();
  if(name==='choose-source'){const result=await api('chooseSource');if(!result.canceled){S.draft.source=result;S.draft.keyLoaded=false;S.draft.selfId='';if($('#dialog').open)showImport();else renderView();}return;}
  if(name==='choose-media'){const result=await api('chooseMediaRoot');if(!result.canceled){S.settings=result;await api('refresh');S.boot=await api('bootstrap');S.results={};await loadView();}return;}
  if(name==='choose-decoder'){const result=await api('chooseDecoder');if(!result.canceled){S.settings=result;notify(t('savedNotice'));}return;}
  if(name==='key-info'||name==='capture-key'){const result=await api(name==='key-info'?'importKeyInfo':'captureKey');if(result.loaded){S.draft.keyLoaded=true;S.draft.selfId=result.accountId||S.draft.selfId;$('#self-id').value=S.draft.selfId;$('#database-key').placeholder='✓';notify(t('savedNotice'));}return;}
  if(name==='export'){const view=S.view==='exports'?'search':S.view;const result=await api('export',{format:node.dataset.format,options:view==='chats'?{...S.filters.chats,thread:S.chatThread,groupsOnly:false}:scopeOptions(view),scope:view});if(!result.canceled)notify(t('exportDone')+' · '+number(result.records));return;}
  if(name==='export-report'){const result=await api('export',{format:'html',scope:'report',options:{start:S.year+'-01-01',end:S.year+'-12-31',groupsOnly:false,tracked:S.settings.tracked||[]}});if(!result.canceled)notify(t('exportDone'));return;}
  if(name==='run-ai'){if(!S.modelPreview)return;const id=S.modelPreview.id;S.modelPreview=null;node.disabled=true;const result=await api('modelRun',{id});if(!result.canceled){S.modelResult=result;renderView();}return;}
  if(name==='lock'){if(!S.settings.lockEnabled)return navigate('settings');await api('lock');S.boot=await api('bootstrap');renderFrame();return;}
  if(name==='disable-lock'){await api('setLock',{password:''});S.settings.lockEnabled=false;notify(t('savedNotice'));renderView();return;}
  if(name==='project')return api('openLink',{url:'https://github.com/cyf1124906008-ai/GroupPulse'});
  if(name==='close-dialog')return $('#dialog').close();
  if(name==='reveal-resource')return api('revealResource',{key:node.dataset.key});
  if(name==='image-preview'){const dialog=$('#dialog');dialog.innerHTML=`<div class="dialog-header"><h2>${e(t('image'))}</h2>${button('close','close-dialog','quiet')}</div><img class="large-preview" src="${e(node.dataset.preview)}" alt="${e(t('image'))}">`;dialog.showModal();return;}
  if(name==='retry-image'){const box=node.closest('.media-box'),img=box.querySelector('img');box.classList.remove('failed');node.hidden=true;const url=new URL(img.src);url.searchParams.set('retry',String(Date.now()));img.src=url.href;return;}
}
document.addEventListener('click',event=>{const node=event.target.closest('[data-action]');if(!node||['language','group','group-query','auto-collect'].includes(node.dataset.action))return;event.preventDefault();void action(node.dataset.action,node).catch(error=>notify(explain(error),true));});
document.addEventListener('input',event=>{const node=event.target;if(node.dataset.bind&&node.type!=='password')setPath(node.dataset.bind,node.type==='checkbox'?node.checked:node.value);if(node.dataset.action==='group-query'){S.groupQuery=node.value;$('#scope-groups').innerHTML=scopeGroups();}});
document.addEventListener('change',event=>{const node=event.target;if(node.dataset.bind&&node.type!=='password')setPath(node.dataset.bind,node.type==='checkbox'?node.checked:node.value);if(node.dataset.bind==='filters.market.scope'){renderView();return;}if(['language','group'].includes(node.dataset.action))void action(node.dataset.action,node).catch(error=>notify(explain(error),true));if(node.dataset.action==='auto-collect')void saveSettings({autoCollect:node.checked}).catch(error=>notify(explain(error),true));});
document.addEventListener('error',event=>{const image=event.target;if(image.tagName!=='IMG')return;if(image.dataset.hideOnError){image.hidden=true;return;}const box=image.closest('.media-box');if(box){box.classList.add('failed');box.querySelector('button').hidden=false;}},true);
document.addEventListener('submit',event=>{const form=event.target;if(!form.dataset.form)return;event.preventDefault();void submit(form).catch(error=>notify(explain(error),true));});
async function submit(form){
  remember();const name=form.dataset.form;
  if(name==='unlock'){await api('unlock',{password:$('#unlock-password').value});return start();}
  if(name==='home-search'){S.filters.search.query=$('#home-query').value;S.filters.search.offset=0;delete S.results.search;return navigate('search');}
  if(name==='filters'){if(form.dataset.view==='chats')S.chatReference='';S.filters[form.dataset.view].offset=0;if(S.groupIds?.length===0&&['search','analysis','prices'].includes(form.dataset.view))throw Error('chooseGroupRequired');return loadView();}
  if(name==='market-search'){S.filters.market.limit=60;return loadView();}
  if(name==='thread-search')return loadView();
  if(name==='tracked'){await saveSettings({tracked:$('#tracked-words').value.split(/[,，、;；\n]+/).map(value=>value.trim()).filter(Boolean)});notify(t('savedNotice'));return loadView();}
  if(name==='general'){await saveSettings({theme:$('#theme-setting').value,autoSync:$('#auto-sync').checked,remoteMedia:$('#remote-media').checked});notify(t('savedNotice'));renderFrame();return loadView({cached:true});}
  if(name==='model'){const draft=S.draft.model||S.settings.model||{};await saveSettings({model:{...draft,apiKey:$('#model-key').value}});S.draft.model={...S.settings.model};notify(t('savedNotice'));return renderView();}
  if(name==='lock-password'){await api('setLock',{password:$('#new-password').value});S.settings.lockEnabled=true;notify(t('savedNotice'));return renderView();}
  if(name==='import'){
    const key=$('#database-key')?.value||'',selfId=$('#self-id').value,remember=$('#remember-key')?.checked!==false;
    const control=form.querySelector('button[type=submit]');control.disabled=true;
    try{await api('import',{token:S.draft.source.token,key,selfId,remember});if($('#dialog').open)$('#dialog').close();S.draft.source=null;S.boot=await api('bootstrap');S.settings=S.boot.settings;S.results={};S.groups=[];S.selected=null;S.view='overview';renderFrame();return loadView();}finally{control.disabled=false;}
  }
  if(name==='ai-preview'){S.modelPreview=await api('modelPreview',{question:$('#ai-question').value||t('questionHint'),options:scopeOptions('analysis'),samples:30});return renderView();}
  if(name==='report'){S.year=Math.min(2100,Math.max(2000,Number(S.year)||new Date().getFullYear()));return loadView();}
}
window.groupPulse.onProgress(progress=>{const node=$('#sync-stamp');if(node)node.textContent=progress.phase==='idle'?stamp():progress.phase==='error'?t('OPERATION_FAILED'):t('syncing')+(progress.current?' · '+number(progress.current):'');});
window.groupPulse.onChanged(async event=>{try{remember();const before=S.boot?.current?.source;S.boot=await api('bootstrap');if(S.boot.locked){renderFrame();return;}S.settings=S.boot.settings;if(before&&before!==S.boot.current?.source){S.selected=null;S.messages.clear();S.groups=[];S.results={};}if($('#sync-stamp'))$('#sync-stamp').textContent=stamp();if(S.view==='settings'||$('#dialog').open)return;if(S.view==='market'&&S.settings.autoCollect===false)return;S.results={};await loadView();}catch(error){notify(explain(error),true);}});
document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='f'){event.preventDefault();const field=$('#page input[type=search]');field?.focus();field?.select();}if(event.key==='Escape'&&S.selected){S.selected=null;renderDrawer();}});
async function start(){S.boot=await api('bootstrap');S.settings=S.boot.settings;L.language=S.settings.language||'zh-CN';S.draft.model={...(S.settings.model||{})};renderFrame();if(!S.boot.locked)await loadView();}
void start().catch(error=>{ $('#application').textContent=explain(error); });
})();
